% @brief 计算矩阵的行列式和最大特征值模，并保存六位小数结果。
M = [2 -1 0 0; -1 2 -1 0; 0 -1 2 -1; 0 0 -1 2];
determinant = det(M);
maxAbsEigenvalue = max(abs(eig(M)));
assert(abs(determinant - 5) < 1e-12);
assert(abs(maxAbsEigenvalue - (2 + 2*cos(pi/5))) < 1e-12);
resultText = sprintf('{"determinant": %.6f, "maxAbsEigenvalue": %.6f}\n', determinant, maxAbsEigenvalue);
outputPath = fullfile(pwd, 'result.json');
[fid, message] = fopen(outputPath, 'w');
assert(fid ~= -1, '无法打开结果文件: %s', message);
writtenCount = fprintf(fid, '%s', resultText);
closeStatus = fclose(fid);
assert(writtenCount == numel(resultText) && closeStatus == 0, '结果文件写入失败。');
savedText = fileread(outputPath);
savedResult = jsondecode(savedText);
assert(strcmp(savedText, resultText));
assert(savedResult.determinant == round(determinant, 6));
assert(savedResult.maxAbsEigenvalue == round(maxAbsEigenvalue, 6));
fprintf('MATLAB: %s\n当前目录: %s\n结果文件: %s\n%s', version, pwd, outputPath, savedText);

